(5146,'|cffff0000Unable to send yell because your message contained reserved words.|r','|cffff0000외치기에 예약된 단어가 포함되어 있어 전송할 수 없습니다.|r','|cffff0000Impossible d\'envoyer le cri car votre message contient des mots réservés.|r','|cffff0000Ruf konnte nicht gesendet werden, da Ihre Nachricht reservierte Wörter enthielt.|r','|cffff0000无法发送大喊，因为您的消息包含保留字。|r','|cffff0000無法傳送大喊，因為您的訊息包含保留字。|r','|cffff0000No se puede enviar el grito porque tu mensaje contenía palabras reservadas.|r','|cffff0000No se puede enviar el grito porque tu mensaje contenía palabras reservadas.|r','|cffff0000Невозможно отправить крик, так как ваше сообщение содержит зарезервированные слова.|r'),
(6604,'You cannot say, yell or emote until you become level {}.','레벨 {}이(가) 되기 전에는 일반 대화, 외침 또는 감정표현을 사용할 수 없습니다.',NULL,'Ihr müsst mindestens Level {} sein, bevor Ihr sprechen, rufen oder emotes nutzen dürft.','你的等级必须大于|CFF9900CC{}|R才可以说话或者使用表情。',NULL,'No puedes decir, gritar ni expresar emociones hasta que alcances el nivel {}.','No puedes decir, gritar ni expresar emociones hasta que alcances el nivel {}.',NULL),
(6605,'You cannot whisper until you become level {}.','레벨 {}이(가) 되기 전에는 귓속말을 보낼 수 없습니다.',NULL,'Ihr müsst mindestens Level {} sein, bevor Ihr flüstern dürft.','你的等级大于|CFF9900CC{}|R才可以说悄悄话。',NULL,'No puedes susurrar hasta que alcances el nivel {}.','No puedes susurrar hasta que alcances el nivel {}.',NULL),
(6606,'You cannot write to channels until you become level {}.','레벨 {}이(가) 되기 전에는 채널에 글을 쓸 수 없습니다.',NULL,'Ihr müsst mindestens Level {} sein, bevor Ihr in Channels schreiben dürft.','你的等级大于|CFF9900CC{}|R才可以使用聊天频道。',NULL,'No puedes escribir en canales hasta que alcances el nivel {}.','No puedes escribir en canales hasta que alcances el nivel {}.',NULL),
(6607,'You cannot use auction until you become level {}.','레벨 {}이(가) 되기 전에는 경매장을 이용할 수 없습니다.',NULL,'Ihr müsst mindestens Level {} sein, bevor Ihr das Auktionshaus nutzen dürft.','你的等级大于|CFF9900CC{}|R才可以使用拍卖行。',NULL,'No puedes usar la subasta hasta que alcances el nivel {}.','No puedes usar la subasta hasta que alcances el nivel {}.',NULL),
(6608,'You cannot write tickets until you become level {}.','레벨 {}이(가) 되기 전에는 문의를 작성할 수 없습니다.',NULL,'Ihr müsst mindestens Level {} sein, bevor Ihr Tickets schreiben dürft.','你的等级大于|CFF9900CC{}|R才可以给GM发送建议。',NULL,'No podrás escribir tickets hasta que alcances el nivel {}.','No podrás escribir tickets hasta que alcances el nivel {}.',NULL),
